  const shownImage=(focusPreviewVisible&&data.focusPreview?.image)||(cam.live&&page==='capture'&&!modal)||((!compare&&rendered)||photo?.preview);
  const propertyControl=(key,compact=false)=>{const p=cam.properties?.[key],disabled=!cam.connected||!p?.writable||!!busy||!!data.interval||sequenceBusy;if(key==='compensation')return <ExposureCompensation key={key} property={p} disabled={disabled} onChange={value=>run('property',()=>api.property({key,value}))}/>;return <label className={cx('property',compact&&'compact')} key={key}><span>{!compact&&<EosIcon kind={key} value={p?.value} size={15}/>} {labels()[key]}</span><div className="select-wrap">{compact&&<LcdReadout kind={key} value={p?.choices?.find(c=>c.value===p.value)?.label}/>}<Select iconKind={['driveMode','whiteBalance','afMode','liveAfMode','imageQuality'].includes(key)?key:undefined} aria-label={labels()[key]} value={p?.value??''} title={!cam.connected?t("desktop.connect_a_camera"):!p?.writable?t("desktop.unavailable"):t("desktop.edit")} disabled={disabled} onChange={e=>run('property',()=>api.property({key,value:Number(e.target.value)}))}>{p?.choices?.length?p.choices.map(c=><option key={c.value} value={c.value} disabled={key==='colorTemperature'&&!p.allowed?.includes(c.value)}>{legacy(c.label)}</option>):<option value="">—</option>}</Select></div></label>;};
  const previewToolbar=<div className="preview-toolbar"><div className="segmented compact"><button className={grid?'active':''} onClick={()=>{setGrid(!grid);setting('grid',!grid);}} title={t("desktop.rule_of_thirds")} aria-label={t("desktop.composition_grid")}><Grid3X3 size={16}/></button><button onClick={()=>setZoom(z=>z===1?2:1)} disabled={!shownImage} title={t("desktop.zoom_100_200")} aria-label={t("desktop.zoom")}><Maximize2 size={16}/></button></div><IconButton icon={SlidersHorizontal} title={t("desktop.composition_guides")} onClick={()=>setModal('composition')}/><div className="zoom-control"><IconButton icon={Minus} title={t("desktop.zoom_out")} onClick={()=>setZoom(z=>Math.max(.5,z-.25))} disabled={!shownImage}/><span>{Math.round(zoom*100)}%</span><IconButton icon={Plus} title={t("desktop.zoom_in")} onClick={()=>setZoom(z=>Math.min(4,z+.25))} disabled={!shownImage}/></div>{photo?<div className="preview-file"><span className="preview-file-name" title={photo.name}>{photo.name}</span><span>{bytes(photo.size)}</span></div>:<span className="muted small">{t("desktop.preview")}</span>}<IconButton icon={FolderOpen} title={t("desktop.open_capture_folder")} onClick={()=>api.reveal({})}/></div>;
